mapper.select:
SELECT event_schedule_id as eventScheduleId, ticket_open_at as ticketOpenAt, event_date as eventDate
FROM tb_event_schedule 
WHERE event_id = #{eventId}

SELECT e.event_id as eventId, e.title, es.event_date as eventDate, v.venue_name as venueName, e.genre FROM tb_event e LEFT JOIN tb_event_schedule es ON e.event_id = es.event_id LEFT JOIN tb_venue v ON es.venue_id = v.venue_id WHERE e.account_id = #{accountId} AND e.status = 'APPROVED' AND es.event_date >= NOW()
AND (es.event_date, e.event_id) >= (#{cursorDate}, #{cursorId})
AND e.genre = #{genre}
ORDER BY es.event_date ASC, e.event_id ASC
LIMIT #{limit}

mapper.update:
UPDATE tb_event
SET status = #{status}, updated_at = NOW()
WHERE event_id = #{eventId}
